import networkx as nx
import json
import os
import pandas as pd
import numpy as np
from scipy.optimize import milp, LinearConstraint, Bounds
from scipy.sparse import lil_matrix
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build and locally improve a minimum union-cost directed broadcast topology."""
    topology = BroadCastTopology(src, dsts, num_partitions)

    # Costless/missing-cost edges must not accidentally receive NetworkX's
    # default unit weight.  Source incoming edges and loops cannot help a
    # source-rooted broadcast.
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bad_edges = []
    for u, v, data in h.edges(data=True):
        cost = data.get("cost")
        try:
            if cost is None or float(cost) < 0:
                bad_edges.append((u, v))
        except (TypeError, ValueError):
            bad_edges.append((u, v))
    h.remove_edges_from(bad_edges)

    # BroadCastTopology is keyed by destination, so duplicate names cannot
    # represent distinct output obligations.
    unique_dsts = list(dict.fromkeys(dsts))
    if not unique_dsts:
        return topology

    def base_distance(dst):
        try:
            return nx.dijkstra_path_length(h, src, dst, weight="cost")
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            return float("inf")

    distances = {dst: base_distance(dst) for dst in unique_dsts}
    reachable = [dst for dst in unique_dsts if distances[dst] != float("inf")]

    # Preserve the parent behavior for ordinary reachable instances.  Empty
    # paths are valid for src itself; unreachable destinations retain None.
    if not reachable:
        return topology

    ascending = sorted(reachable, key=lambda d: (distances[d], str(d)))
    descending = list(reversed(ascending))
    input_order = list(reachable)
    orders = []
    for order in (ascending, descending, input_order):
        if order not in orders:
            orders.append(order)

    def route_for_order(order):
        """Select shared edges with a bounded path-pool MILP, then polish routes."""
        # Construct bounded one- and two-relay broadcast clusters.  Shortest
        # paths are cached once per source/relay, so each candidate is only a
        # union-cost assembly rather than another graph search.
        try:
            src_lengths, src_paths = nx.single_source_dijkstra(
                h, src, weight="cost"
            )
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            src_lengths, src_paths = {}, {}

        relay_scores = {}
        for dst in order:
            node_path = src_paths.get(dst)
            if node_path is None:
                continue
            for node in node_path:
                relay_scores[node] = relay_scores.get(node, 0) + 1

        ranked = sorted(
            (node for node in relay_scores if node != src),
            key=lambda node: (
                -relay_scores[node],
                float(src_lengths.get(node, float("inf"))),
                str(node),
            ),
        )
        relays = [src] + ranked[:15]

        relay_paths = {src: src_paths}
        for relay in relays[1:]:
            try:
                _, paths = nx.single_source_dijkstra(
                    h, relay, weight="cost"
                )
                relay_paths[relay] = paths
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                relay_paths[relay] = {}

        def edge_cost(edge_path):
            return sum(float(h[u][v]["cost"]) for u, v in edge_path)

        def joined_path(relay, dst):
            first = src_paths.get(relay)
            second = relay_paths.get(relay, {}).get(dst)
            if first is None or second is None:
                return None
            first_edges = list(zip(first, first[1:]))
            second_edges = list(zip(second, second[1:]))
            return tuple(first_edges + second_edges)

        def candidate_for(relay_set):
            """Return the least-cost shared-edge candidate for a relay set."""
            routes = {}
            for dst in order:
                options = [
                    joined_path(relay, dst)
                    for relay in relay_set
                    if joined_path(relay, dst) is not None
                ]
                if not options:
                    return None
                routes[dst] = min(
                    options,
                    key=lambda path: (
                        edge_cost(path), len(path), tuple(map(str, path))
                    ),
                )
            active = frozenset(edge for path in routes.values() for edge in path)
            return routes, active, sum(
                float(h[u][v]["cost"]) for u, v in active
            )

        # First retain the parent's best relay solution as a guaranteed
        # feasible incumbent.  The path pool below can only improve it.
        relay_sets = [(src,)]
        relay_sets.extend((relay,) for relay in relays[1:])
        pair_count = 0
        for i, first in enumerate(relays[1:]):
            for second in relays[i + 2:]:
                if pair_count >= 120:
                    break
                relay_sets.append((first, second))
                pair_count += 1
            if pair_count >= 120:
                break

        states = [
            state for relay_set in relay_sets
            for state in (candidate_for(relay_set),)
            if state is not None
        ]
        if not states:
            return float("inf"), {}

        incumbent = min(
            states,
            key=lambda state: (
                state[2],
                len(state[1]),
                tuple(sorted((str(u), str(v)) for u, v in state[1])),
            ),
        )

        # Build a bounded, globally shared path pool.  Penalizing frequently
        # used edges exposes alternate corridors without unbounded searches.
        pool = {dst: [incumbent[0][dst]] for dst in order}
        usage = {}
        for path in incumbent[0].values():
            for edge in path:
                usage[edge] = usage.get(edge, 0) + 1

        for _ in range(6):
            weights = {
                (u, v): float(data["cost"]) * (
                    1.0 + 0.35 * usage.get((u, v), 0)
                )
                for u, v, data in h.edges(data=True)
            }
            for dst in order:
                try:
                    nodes = nx.dijkstra_path(
                        h, src, dst,
                        weight=lambda u, v, data: weights[(u, v)],
                    )
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    continue
                path = tuple(zip(nodes, nodes[1:]))
                if path not in pool[dst]:
                    pool[dst].append(path)
                    for edge in path:
                        usage[edge] = usage.get(edge, 0) + 1

        # Add one path per destination through the incumbent's active
        # arborescence, when the active edges contain such a route.
        active_graph = nx.DiGraph()
        active_graph.add_edges_from(incumbent[1])
        for dst in order:
            try:
                nodes = nx.dijkstra_path(
                    active_graph, src, dst,
                    weight=lambda u, v, data: float(h[u][v]["cost"]),
                )
                path = tuple(zip(nodes, nodes[1:]))
                if path not in pool[dst]:
                    pool[dst].append(path)
            except (nx.NetworkXNoPath, nx.NodeNotFound, KeyError):
                pass

        path_items = [
            (dst, path) for dst in order for path in pool[dst]
        ]
        active_edges = sorted(
            {edge for _, path in path_items for edge in path},
            key=lambda edge: (str(edge[0]), str(edge[1])),
        )

        if len(path_items) <= 160 and len(active_edges) <= 500:
            path_index = {item: i for i, item in enumerate(path_items)}
            edge_index = {
                edge: len(path_items) + i
                for i, edge in enumerate(active_edges)
            }
            nvars = len(path_items) + len(active_edges)
            objective = np.zeros(nvars, dtype=float)
            objective[len(path_items):] = np.asarray(
                [float(h[u][v]["cost"]) for u, v in active_edges],
                dtype=float,
            )

            row_count = len(order) + sum(
                len(set(path)) for _, path in path_items
            )
            matrix = lil_matrix((row_count, nvars), dtype=float)
            lower = np.full(row_count, -np.inf, dtype=float)
            upper = np.full(row_count, np.inf, dtype=float)
            row = 0

            for dst in order:
                for path in pool[dst]:
                    matrix[row, path_index[(dst, path)]] = 1.0
                lower[row] = upper[row] = 1.0
                row += 1

            for _, path in path_items:
                x_index = path_index[(_, path)]
                for edge in set(path):
                    matrix[row, x_index] = 1.0
                    matrix[row, edge_index[edge]] = -1.0
                    upper[row] = 0.0
                    row += 1

            try:
                result = milp(
                    objective,
                    integrality=np.ones(nvars, dtype=np.int8),
                    bounds=Bounds(
                        np.zeros(nvars, dtype=float),
                        np.ones(nvars, dtype=float),
                    ),
                    constraints=LinearConstraint(
                        matrix.tocsr(), lower, upper
                    ),
                    options={"time_limit": 2.0},
                )
                # A time-limited MILP can still provide a valid incumbent.
                if result.x is not None and np.all(np.isfinite(result.x)):
                    chosen = {}
                    for i, (dst, path) in enumerate(path_items):
                        if result.x[i] > 0.5:
                            chosen[dst] = path
                    if len(chosen) == len(order):
                        active = frozenset(
                            edge for path in chosen.values() for edge in path
                        )
                        candidate = (
                            chosen,
                            active,
                            sum(float(h[u][v]["cost"]) for u, v in active),
                        )
                        if candidate[2] < incumbent[2]:
                            incumbent = candidate
            except (ValueError, RuntimeError, TypeError):
                pass

        beam = [incumbent]

        paths = dict(beam[0][0])
        counts = {}
        for edge_path in paths.values():
            for edge in edge_path:
                counts[edge] = counts.get(edge, 0) + 1

        def marginal(u, v, data):
            return 0.0 if counts.get((u, v), 0) > 0 else float(data["cost"])

        # Coordinate descent: with all other routes held fixed, Dijkstra with
        # their edges free gives the best union-cost route for this destination.
        for _ in range(3):
            changed = False
            for dst in order:
                old_path = paths.get(dst)
                if old_path is None:
                    continue
                for edge in old_path:
                    counts[edge] -= 1
                    if counts[edge] == 0:
                        del counts[edge]
                try:
                    node_path = nx.dijkstra_path(h, src, dst, weight=marginal)
                    new_path = tuple(zip(node_path, node_path[1:]))
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    new_path = old_path
                if new_path != old_path:
                    changed = True
                paths[dst] = new_path
                for edge in new_path:
                    counts[edge] = counts.get(edge, 0) + 1
            if not changed:
                break

        union_cost = sum(float(h[u][v]["cost"]) for u, v in counts)
        return union_cost, paths

    best_cost = float("inf")
    best_paths = {}
    for order in orders:
        cost, paths = route_for_order(order)
        if cost < best_cost:
            best_cost = cost
            best_paths = paths

    for dst in unique_dsts:
        edge_pairs = best_paths.get(dst)
        if edge_pairs is None:
            continue
        edges = [[u, v, G[u][v]] for u, v in edge_pairs]
        for partition in range(topology.num_partitions):
            topology.set_dst_partition_paths(dst, partition, list(edges))

    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(
        self,
        src: str,
        dsts: List[str],
        num_partitions: int = 4,
        paths: Dict[str, SingleDstPath] = None,
    ):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {
                dst: {str(i): None for i in range(num_partitions)}
                for dst in dsts
            }

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)


def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(
            os.path.join(current_dir, "profiles/throughput.csv")
        )
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(
            row["src_region"],
            row["dst_region"],
            cost=None,
            throughput=num_vms * row["throughput_sent"] / 1e9,
        )

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    no_cost_pairs = []
    for edge in G.edges.data():
        edge_src, edge_dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((edge_src, edge_dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    return BroadCastTopology(src, dsts, num_partitions)


def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    return search_algorithm(src, dsts, G, num_partitions)

